    def create_session(self, session_id=None):
        if session_id is None:
            session_id = str(uuid.uuid4())[:8]
        workspace_path = os.path.join(self.workspace_base, f"session_{session_id}")
        os.makedirs(workspace_path, exist_ok=True)
        self.active_sessions[session_id] = {
            "workspace": workspace_path,
            "created_at": time.time(),
            "files": [],
            "execution_history": [],
            "status": "active"
        }
        self.session_locks[session_id] = threading.Lock()
        return {
            "session_id": session_id,
            "workspace": workspace_path,
            "status": "created",
            "available_languages": list(self.language_configs.keys())
        }

    def get_session(self, session_id):
        if session_id not in self.active_sessions:
            return None
        return self.active_sessions[session_id]

    def create_file(self, session_id, filename, content):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        filepath = os.path.join(session["workspace"], filename)
        parent_dir = os.path.dirname(filepath)
        if parent_dir and not os.path.exists(parent_dir):
            os.makedirs(parent_dir, exist_ok=True)
        with open(filepath, "w", encoding="utf-8") as f:
            f.write(content)
        if filename not in session["files"]:
            session["files"].append(filename)
        return {
            "status": "created",
            "filename": filename,
            "filepath": filepath,
            "size": len(content)
        }

    def read_file(self, session_id, filename):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        filepath = os.path.join(session["workspace"], filename)
        if not os.path.exists(filepath):
            return {"error": "File not found", "filename": filename}
        with open(filepath, "r", encoding="utf-8") as f:
            content = f.read()
        return {
            "status": "success",
            "filename": filename,
            "content": content,
            "size": len(content)
        }

    def delete_file(self, session_id, filename):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        filepath = os.path.join(session["workspace"], filename)
        if not os.path.exists(filepath):
            return {"error": "File not found", "filename": filename}
        os.remove(filepath)
        if filename in session["files"]:
            session["files"].remove(filename)
        return {
            "status": "deleted",
            "filename": filename
        }

    def list_files(self, session_id):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        files = []
        workspace = session["workspace"]
        for root, dirs, filenames in os.walk(workspace):
            for filename in filenames:
                full_path = os.path.join(root, filename)
                rel_path = os.path.relpath(full_path, workspace)
                stat = os.stat(full_path)
                files.append({
                    "name": rel_path,
                    "size": stat.st_size,
                    "modified": stat.st_mtime
                })
        return {
            "status": "success",
            "files": files,
            "count": len(files)
        }

    def execute_code(self, session_id, language, code=None, filename=None, timeout=300, args=None):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        language = language.lower()
        if language not in self.language_configs:
            return {"error": f"Unsupported language: {language}", "supported": list(self.language_configs.keys())}
        config = self.language_configs[language]
        workspace = session["workspace"]
        if code:
            if filename:
                code_filename = filename
            else:
                code_filename = f"main{config['extension']}"
            code_filepath = os.path.join(workspace, code_filename)
            with open(code_filepath, "w", encoding="utf-8") as f:
                f.write(code)
            if code_filename not in session["files"]:
                session["files"].append(code_filename)
        elif filename:
            code_filename = filename
            code_filepath = os.path.join(workspace, code_filename)
            if not os.path.exists(code_filepath):
                return {"error": f"File not found: {filename}"}
        else:
            return {"error": "Either code or filename must be provided"}
        nix_packages = " ".join(config["nix_packages"])
