                        execution_result["stdout"] = compile_result.stdout
                        execution_result["exit_code"] = compile_result.returncode
                        session["execution_history"].append(execution_result)
                        return execution_result
                    run_command = f"cd {workspace} && nix-shell -p {nix_packages} --run '{config['run_cmd']}'"
                elif language in ["c", "cpp"]:
                    compile_command = f"cd {workspace} && nix-shell -p {nix_packages} --run '{config['compile_cmd']} {code_filename}'"
                    compile_result = subprocess.run(
                        compile_command,
