    def install_package(self, session_id, language, packages):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        workspace = session["workspace"]
        language = language.lower()
        results = []
        for package in packages:
            if language in ["python", "python3"]:
                cmd = f"nix-shell -p python311 python311Packages.pip --run 'pip install --target={workspace}/.packages {package}'"
            elif language in ["javascript", "nodejs"]:
                cmd = f"cd {workspace} && nix-shell -p nodejs_20 --run 'npm install {package}'"
            elif language == "go":
                cmd = f"cd {workspace} && nix-shell -p go --run 'go get {package}'"
            elif language == "rust":
                cmd = f"cd {workspace} && nix-shell -p rustc cargo --run 'cargo add {package}'"
            elif language == "ruby":
                cmd = f"cd {workspace} && nix-shell -p ruby --run 'gem install {package} --install-dir={workspace}/.gems'"
            else:
                results.append({"package": package, "status": "error", "error": f"Package installation not supported for {language}"})
                continue
            try:
                result = subprocess.run(
                    cmd,
                    shell=True,
                    capture_output=True,
                    text=True,
                    timeout=120,
                    cwd=workspace
                )
                results.append({
                    "package": package,
                    "status": "success" if result.returncode == 0 else "error",
                    "stdout": result.stdout,
                    "stderr": result.stderr
                })
            except Exception as e:
                results.append({"package": package, "status": "error", "error": str(e)})
        return {"status": "completed", "results": results}

    def get_execution_history(self, session_id, limit=10):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        history = session["execution_history"][-limit:]
        return {
            "status": "success",
            "history": history,
            "total_executions": len(session["execution_history"])
        }

    def cleanup_session(self, session_id):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        workspace = session["workspace"]
        if os.path.exists(workspace):
            shutil.rmtree(workspace)
        del self.active_sessions[session_id]
        if session_id in self.session_locks:
            del self.session_locks[session_id]
        return {"status": "cleaned", "session_id": session_id}

    def cleanup_old_sessions(self, max_age_hours=2):
        current_time = time.time()
        max_age_seconds = max_age_hours * 3600
        cleaned = []
        for session_id in list(self.active_sessions.keys()):
            session = self.active_sessions[session_id]
            if current_time - session["created_at"] > max_age_seconds:
                self.cleanup_session(session_id)
                cleaned.append(session_id)
        return {"status": "cleanup_complete", "cleaned_sessions": cleaned}

    def get_workspace_info(self, session_id):
        session = self.get_session(session_id)
        if not session:
            return {"error": "Session not found", "session_id": session_id}
        workspace = session["workspace"]
        total_size = 0
        file_count = 0
        for root, dirs, files in os.walk(workspace):
            for f in files:
                fp = os.path.join(root, f)
                total_size += os.path.getsize(fp)
                file_count += 1
        return {
            "session_id": session_id,
            "workspace": workspace,
            "file_count": file_count,
            "total_size_bytes": total_size,
            "created_at": session["created_at"],
            "execution_count": len(session["execution_history"]),
            "status": session["status"]
        }


